      {"chapter_number": 7, "chapter_title": "毒虫", "chapter_synopsis": "下山途中，两人误入一片毒虫聚集的腐殖质区。石野凭借野外经验提前察觉到危险，带着林深绕行，但林深的背包不小心蹭到了毒蜂巢。石野被迫用自己的身体掩护林深逃跑，被蛰了多处。林深则利用地形知识找到一条溪流，两人跳进水潭才躲过追击。", "scene_sequence": [{"scene_number": 1, "scene_location": "下山途中的密林，上午", "characters_present": ["石野", "林深"], "scene_purpose": "展示石野的野外直觉", "core_action": "石野突然停下脚步：'不对，有蜂群'，但林深的背包撞到了隐藏的蜂巢", "conflict_point": "蜂群涌出，石野把林深推向相反方向：'往溪流跑！'自己引开蜂群", "emotional_shift": "从'正常行进'的平静 → '生死一线'的紧急", "scene_outcome": "石野被蜂群追赶，身上被蛰了多处"}, {"scene_number": 2, "scene_location": "溪流旁，中午", "characters_present": ["石野", "林深"], "scene_purpose": "展示林深的价值，能力互补", "core_action": "林深想起父亲笔记中提到'遇蜂群入水'，大喊：'跳进水里！'", "conflict_point": "蜂群在水面上盘旋，两人只能在水下憋气，石野意识模糊", "emotional_shift": "从'我帮不上忙'的无力 → '我的知识能救他'的自信", "scene_outcome": "林深拖着半昏迷的石野上岸，用急救知识处理蜂毒"}]},
      {"chapter_number": 8, "chapter_title": "村寨", "chapter_synopsis": "两人终于抵达老刀所在的独龙族村寨。村寨位于深山中的河谷地带，与外界几乎隔绝。老刀是当年给石守山和林远途带路的猎人，也是最后见过两位父亲的人。老刀沉默寡言，但答应给他们提供补给和进山路线。", "scene_sequence": [{"scene_number": 1, "scene_location": "独龙族村寨入口，黄昏", "characters_present": ["石野", "林深", "老刀"], "scene_purpose": "引入关键配角老刀，获得父辈线索", "core_action": "老刀打量着两人，目光在石野脸上停留：'你长得像你父亲'", "conflict_point": "老刀说出二十年前的事：'我给他们带过路，送到前面的河谷'", "emotional_shift": "从'只是传说'的遥远 → '有人真的见过父亲'的真实与痛苦", "scene_outcome": "老刀邀请两人到他家休息"}, {"scene_number": 2, "scene_location": "村寨中央的议事场所，晚上，篝火旁", "characters_present": ["石野", "林深", "老刀", "阿普爷爷"], "scene_purpose": "引入阻碍型配角阿普爷爷", "core_action": "阿普爷爷用独龙语和老刀争论，然后转向两人", "conflict_point": "阿普爷爷的警告：'那座城是祖先的安息地，不是给你们探险的。进去的人，山会留下'", "emotional_shift": "从'找到线索'的兴奋 → '这是禁忌'的不安", "scene_outcome": "阿普爷爷叹气离去：'你们会后悔的'"}]},
      {"chapter_number": 9, "chapter_title": "路线图", "chapter_synopsis": "老刀给两人看了一张手绘的进山路线图，上面标注着危险区域和水源位置。石野发现这张路线图上的一些标记与父亲笔记中的草图吻合。林深则从路线图的标注方式中发现老刀用的某些符号与父亲笔记中的符号一致。", "scene_sequence": [{"scene_number": 1, "scene_location": "老刀家，晚上，油灯下", "characters_present": ["石野", "林深", "老刀"], "scene_purpose": "获得关键道具——路线图", "core_action": "老刀从木箱底层取出一张泛黄的羊皮纸", "conflict_point": "石野发现符号与父亲笔记一致，质问老刀：'你早就知道我们会来？'", "emotional_shift": "从'他只是普通向导' → '他知道更多'的怀疑", "scene_outcome": "老刀讲述二十年前石守山把图交给他时说的话"}, {"scene_number": 2, "scene_location": "老刀家外，夜晚", "characters_present": ["石野", "林深"], "scene_purpose": "展示石野的内心变化", "core_action": "石野望着远处的山脉轮廓，林深走到他身边", "conflict_point": "石野的声音低沉：'他不是准备好让我来找他，是准备好让我放弃'", "emotional_shift": "从'父亲是个冒险者' → '父亲是个不负责任的人'的痛苦认知", "scene_outcome": "林深站在石野身边，两人一起望着黑暗中的山脉"}]},
      {"chapter_number": 10, "chapter_title": "山洪", "chapter_synopsis": "两人按照路线图继续前进，进入一条狭窄的河谷。夏季的暴雨突然来袭，山洪暴发。两人被困在河谷中央的一块巨石上，水位不断上涨。石野把唯一的登山绳绑在林深身上，让他先爬到对岸，自己则攀爬湿滑的岩壁。在攀爬过程中，石野失手坠落，千钧一发之际，林深用身体死死拽住绳索。", "scene_sequence": [{"scene_number": 1, "scene_location": "河谷，上午，原本晴朗的天空突然乌云密布", "characters_present": ["石野", "林深"], "scene_purpose": "建立危险环境", "core_action": "石野抬头看天，脸色大变：'暴雨要来了，我们必须立刻离开河谷！'", "conflict_point": "林深体力不支跑不快；身后山谷传来轰隆隆的声音——洪水来了", "emotional_shift": "从'正常行进' → '生死一线'的紧急", "scene_outcome": "两人拼命向河谷边缘跑去"}, {"scene_number": 2, "scene_location": "河谷中央巨石上，暴雨倾盆，水位暴涨", "characters_present": ["石野", "林深"], "scene_purpose": "第一幕高潮——托命时刻", "core_action": "石野把登山绳绑在林深腰上：'我固定好这边，你先爬过去！'", "conflict_point": "林深拒绝：'你先走！'石野暴怒：'我体力比你好，我殿后！'", "emotional_shift": "从'各自求生' → '我必须保护他'的决绝", "scene_outcome": "林深开始攀爬绳索，石野在下方固定锚点"}, {"scene_number": 3, "scene_location": "对岸岩壁，暴雨中，石野攀爬时失手", "characters_present": ["石野", "林深"], "scene_purpose": "托命的高潮时刻", "core_action": "石野脚下一滑坠落，绳索瞬间绷紧；林深用身体死死拽住绳索，手背被勒得皮开肉绽", "conflict_point": "林深的力量不足以把石野拉上来，但他咬紧牙关绝不松手", "emotional_shift": "从'我要活下去' → '他宁愿勒断手也不放弃我'的震撼", "scene_outcome": "石野终于抓住岩壁上的凸起，两人合力爬上了安全地带"}]},
      {"chapter_number": 11, "chapter_title": "包扎", "chapter_synopsis": "两人在山洞中躲避暴雨，处理伤口。林深的手背被勒得血肉模糊，石野小心翼翼地为他清洗、上药、包扎。石野承认他从小就嫉妒林深'有父亲教'，林深则承认他一直羡慕石野'不用背负那么多期望'。两人发现，虽然成长轨迹不同，但他们都活在父亲的阴影下。", "scene_sequence": [{"scene_number": 1, "scene_location": "山洞内，暴雨刚停，水声轰鸣", "characters_present": ["石野", "林深"], "scene_purpose": "展示托命后的情感交流", "core_action": "石野为林深包扎手背，动作小心翼翼", "conflict_point": "林深问：'你为什么回来救我？'石野沉默片刻：'因为我只有你了'", "emotional_shift": "从'发小关系' → '我无法承受失去你'的深度坦诚", "scene_outcome": "两人陷入沉默，但气氛不再是尴尬"}, {"scene_number": 2, "scene_location": "山洞外，雨后的山谷，空气清新", "characters_present": ["石野", "林深"], "scene_purpose": "关系质变后的第一次共同展望", "core_action": "两人并肩站在洞口，看向远处云雾缭绕的山峰", "conflict_point": "石野问：'如果我们在那里找到他们的尸体，你打算怎么办？'", "emotional_shift": "从'逃避真相' → '必须面对'的成熟", "scene_outcome": "林深说：'带他们回家'，石野点头：'带他们回家'"}]}
